// Begin static function definitions.
static double
gk_species_omegaH_dt(gkyl_gyrokinetic_app *app, struct gk_species *gks, const struct gkyl_array *fin)
{
  // Compute the time step under which the omega_H mode is stable, dt_omegaH =
  // omegaH_CFL/omega_H.
  // Each species computes its own omega_H as:
  //   omega_H = q_e*sqrt(jacobgeo*n_{s0}/m_s) * omegaH_gf
  // where
  //   - n_{s0} is either a reference, average or max density.
  //   - omegaH_gf = (cmag/(jacobgeo*B^_\parallel))*kpar_max /
  //                 min(sqrt(k_x^2*eps_xx+k_x*k_y*eps_xy+k_y^2*eps_yy+)).
  // and k_x,k_y,k_par are wavenumbers in computational space, and eps_ij is
  // the polarization weight in our field equation.

  if (!(app->field->gkfield_id == GKYL_GK_FIELD_BOLTZMANN ||
        app->field->gkfield_id == GKYL_GK_FIELD_ADIABATIC)) {
    // Obtain the maximum density (using cell centers).
    gk_species_moment_calc(&gks->m0, gks->local, app->local, fin);
    gkyl_array_reduce_range(gks->m0_max, gks->m0.marr, GKYL_MAX, &app->local);

    double m0_max[1];
    if (app->use_gpu) {
      gkyl_cu_memcpy(m0_max, gks->m0_max, sizeof(double), GKYL_CU_MEMCPY_D2H);
    } else {
      m0_max[0] = gks->m0_max[0];
    }
    m0_max[0] *= 1.0 / pow(sqrt(2.0), app->cdim);

    double time_dilation_scale_const =
      gk_fdot_multiplier_get_time_dilation_scale_const(app, &gks->fdot_mult) *
      gk_fdot_multiplier_get_time_dilation_scale_const(app, &gks->collisionless.fdot_mult);

    double omegaH = fabs(gks->info.charge) * sqrt(GKYL_MAX2(0.0, m0_max[0]) / gks->info.mass) *
                    app->omegaH_gf * time_dilation_scale_const * gks->collisionless.scale_fac;

    return omegaH > 1e-20 ? app->cfl_omegaH / omegaH : DBL_MAX;
  } else {
    return DBL_MAX;
  }
}

static double
gk_species_rhs_dynamic(
  gkyl_gyrokinetic_app *app, struct gk_species *species, const struct gkyl_array *fin,
  const struct gkyl_array *fbar_in, struct gkyl_array *rhs, struct gkyl_array **bflux_moms
)
{
  // Gyroaverage the potential if needed.
  species->gyroaverage(app, species, app->field->phi_smooth, species->gyro_phi);

  gkyl_array_clear(species->cflrate, 0.0);
  gkyl_array_clear(rhs, 0.0);

  // Collisionless terms.
  gk_species_collisionless_rhs(app, species, &species->collisionless, fin, rhs);

  // Damping term.
  gk_species_damping_advance(
    app, species, &species->damping, app->field->phi_smooth, fin, fbar_in, species->lte.f_lte, rhs,
    species->cflrate
  );

  // LBO Collisions.
  gk_species_lbo_rhs(app, species, &species->lbo, fin, rhs);

  // BGK collisions.
  gk_species_bgk_rhs(app, species, &species->bgk, fin, rhs);

  // Anomalous diffusion.
  gk_species_anomalous_diff_rhs(app, species, &species->anom_diff, fin, rhs);

  // Line radiation.
  gk_species_radiation_rhs(app, species, &species->rad, fin, rhs);

  // Reactions with charged species.
  gk_species_react_rhs(app, species, &species->react, fin, rhs);

  // Reactions with neutral species.
  gk_species_react_rhs(app, species, &species->react_neut, fin, rhs);

  // BGK source.
  gk_species_source_bgk_rhs(app, species, &species->bgk_src, fin, rhs);

  // Compute and store (in the ghost cell of rhs and in an array in bflux) the boundary fluxes.
  gk_species_bflux_rhs(app, &species->bflux, fin, rhs);

  // Compute moments of the boundary fluxes.
  gk_species_bflux_calc_moms(app, &species->bflux, rhs, bflux_moms);

  // Multiply CFL rate by the df/dt multiplier.
  gk_species_fdot_multiplier_advance_times_cfl(
    app, species, &species->fdot_mult, app->field->phi_smooth, fin, species->cflrate
  );

  // Reduce the CFL frequency and compute stable dt needed by this species.
  app->stat.n_species_omega_cfl += 1;
  struct timespec tm = gkyl_wall_clock();
  gkyl_array_reduce_range(species->omega_cfl, species->cflrate, GKYL_MAX, &species->local);

  double omega_cfl_ho[1];
  if (app->use_gpu) {
    gkyl_cu_memcpy(omega_cfl_ho, species->omega_cfl, sizeof(double), GKYL_CU_MEMCPY_D2H);
  } else {
    omega_cfl_ho[0] = species->omega_cfl[0];
  }

  double dt_out = app->cfl / omega_cfl_ho[0];

  // Apply omega_H constraint on dt.
  species->dt_omegaH = gk_species_omegaH_dt(app, species, fin);
  dt_out = fmin(dt_out, species->dt_omegaH);

  species->dt_cfl_global_ho = dt_out;

  app->stat.species_omega_cfl_tm += gkyl_time_diff_now_sec(tm);
  return dt_out;
}

static double
gk_species_rhs_implicit_dynamic(
  gkyl_gyrokinetic_app *app, struct gk_species *species, const struct gkyl_array *fin,
  struct gkyl_array *rhs, struct gkyl_array **bflux_moms, double dt
{
  double dtmin = DBL_MAX;

  // Compute moments needed by various modules.
  for (int i = 0; i < app->num_species; ++i) {
    struct gk_species *gk_s = &app->species[i];
    gk_species_lbo_moms(app, gk_s, &gk_s->lbo, fin[i]);
    gk_species_bgk_moms(app, gk_s, &gk_s->bgk, fin[i]);
  }
  for (int i = 0; i < app->num_neut_species; ++i) {
    struct gk_neut_species *gk_ns = &app->neut_species[i];
    gk_neut_species_bgk_moms(app, gk_ns, &gk_ns->bgk, fin_neut[i]);
  }

  // Compute cross-species moments needed by various modules.
  for (int i = 0; i < app->num_species; ++i) {
    struct gk_species *gk_s = &app->species[i];

    // Elastic collisions.
    gk_species_lbo_cross_moms(app, gk_s, &gk_s->lbo, fin[i]);
    gk_species_bgk_cross_moms(app, gk_s, &gk_s->bgk, fin[i]);

    // Reactions (e.g. ionization, recombination charge exchange).
    gk_species_react_cross_moms(app, gk_s, &gk_s->react, fin, fin_neut);
    gk_species_react_cross_moms(app, gk_s, &gk_s->react_neut, fin, fin_neut);

    // Line radiation.
    gk_species_radiation_moms(app, gk_s, &gk_s->rad, fin, fin_neut);

    // Scaling.
    gk_species_scaling_cross_moms(app, gk_s, &gk_s->sca, fin, fin_neut);
  }
  for (int i = 0; i < app->num_neut_species; ++i) {
    struct gk_neut_species *gk_ns = &app->neut_species[i];

    // Reactions (e.g. ionization, recombination charge exchange).
    gk_neut_species_react_cross_moms(app, gk_ns, &gk_ns->react_neut, fin, fin_neut);

    // Scaling.
    gk_neut_species_scaling_cross_moms(app, gk_ns, &gk_ns->sca, fin, fin_neut);
  }

  // Compute df/dt (not including sources).
  for (int i = 0; i < app->num_species; ++i) {
    struct gk_species *gk_s = &app->species[i];
    double dt1 = gk_species_rhs(app, gk_s, fin[i], fbar_in[i], fout[i], bflux_out[i]);
    dtmin = fmin(dtmin, dt1);
  }
  for (int i = 0; i < app->num_neut_species; ++i) {
    struct gk_neut_species *gk_ns = &app->neut_species[i];
    double dt1 = gk_neut_species_rhs(app, gk_ns, fin_neut[i], fout_neut[i], bflux_out_neut[i]);
    dtmin = fmin(dtmin, dt1);
  }

  gk_eirene_rhs(app, fin, fout);

  // Sources. Done after df/dt in case boundary fluxes are needed.
  for (int i = 0; i < app->num_species; ++i) {
    gk_species_source_rhs(app, &app->species[i], &app->species[i].src, fin[i], fout[i]);
  }
  for (int i = 0; i < app->num_neut_species; ++i) {
    gk_neut_species_source_rhs(
      app, &app->neut_species[i], &app->neut_species[i].src, fin_neut[i], fout_neut[i]
    );
  }

  // Multiply dfdt (fout) by a factor.
  for (int i = 0; i < app->num_species; ++i) {
    struct gk_species *gks = &app->species[i];
    gk_species_fdot_multiplier_advance_times_rate(
      app, gks, &gks->fdot_mult, app->field->phi_smooth, fin[i], fout[i]
    );
  }

  struct timespec wtm = gkyl_wall_clock();
  double dt_max_rel_diff = 0.01;
  // Check if dtmin is slightly smaller than dt. Use dt if it is
  // (avoids retaking steps if dt changes are very small).
  double dt_rel_diff = (dt - dtmin) / dt;
  if (dt_rel_diff > 0 && dt_rel_diff < dt_max_rel_diff) {
    dtmin = dt;
  }

  // Compute minimum time-step across all processors.
  double dtmin_local = dtmin, dtmin_global;
  gkyl_comm_allreduce_host(app->comm, GKYL_DOUBLE, GKYL_MIN, 1, &dtmin_local, &dtmin_global);
  dtmin = dtmin_global;

  // Don't take a time-step larger that input dt.
  double dta = st->dt_actual = dt < dtmin ? dt : dtmin;
  st->dt_suggested = dtmin;

// Types of df/dt multipliers: M(x,v,t) modifies df/dt -> M * df/dt.
enum gkyl_gyrokinetic_fdot_multiplier_type {
  GKYL_GK_FDOT_MULTIPLIER_NONE = 0, // No multiplier applied.
  GKYL_GK_FDOT_MULTIPLIER_USER_INPUT, // User-provided static profile M(z) via function pointer.
  GKYL_GK_FDOT_MULTIPLIER_LOSS_CONE, // M=1 in confined region, M=0 in the loss cone.
  GKYL_GK_FDOT_MULTIPLIER_CONSTANT, // Dilates time by a fixed constant, time_dilation_scale_const.
  GKYL_GK_FDOT_MULTIPLIER_FIXED_DT, // dt floor from user-specified cfl_dt_min_value.
  GKYL_GK_FDOT_MULTIPLIER_FIXED_FACTOR_TIMES_OMEGA_MAX, // dt floor from user-specified factor times maximum characteristic frequency. Specify cfl_factor_times_omega_max.
  GKYL_GK_FDOT_MULTIPLIER_FIXED_DT_OMEGAH, // dt floor from omega_H, an electrostatic GK wave.
  GKYL_GK_FDOT_MULTIPLIER_DT_SET_BY_SPECIES, // Set the dt floor based on the dt from another species.
  GKYL_GK_FDOT_MULTIPLIER_MASK_F_THRESHOLD, // Dilates time in cells where |J_tot*f| < threshold. Specify f_threshold
  GKYL_GK_FDOT_MULTIPLIER_MASK_F_FRAC_LOCAL, // Dilates time in cells where |J_tot*f| < threshold * local_max. Spatially dependent mask. Specify f_threshold
  GKYL_GK_FDOT_MULTIPLIER_MASK_F_FRAC_GLOBAL // Dilates time in cells where |J_tot*f| < threshold * global_max. Specify f_threshold
};

// Input parameters for a single component of the df/dt multiplier chain.
struct gkyl_gyrokinetic_fdot_multiplier_comp {
  enum gkyl_gyrokinetic_fdot_multiplier_type type; // Type of multiplier (see enum comments above).

  // For USER_INPUT type: function pointer defining M(z).
  void (*profile)(double t, const double *xn, double *fout, void *ctx);
  void *profile_ctx;

  bool cellwise_const; // If true, multiplier is constant within each cell (p=0 basis).
  bool write_diagnostics; // If true, write multiplier array to file.

  // Parameters for time dilation types (FIXED_DT, MASK_F_*):
  double cfl_dt_min_value; // For FIXED_DT: the minimum allowed dt value.
  double f_threshold; // For MASK_F_* types: absolute value (THRESHOLD)
  // or fraction 0-1 (FRAC_LOCAL, FRAC_GLOBAL).
  double
    time_dilation_scale_const; // A constant which multiplies all of fdot and cfl to dilate time. Small number (0,1] so that dt *= 1/time_dilation_scale_const
  double
    cfl_factor_times_omega_max; // For FIXED_FACTOR_TIMES_OMEGA_MAX: the factor multiplied by the maximum characteristic frequency to get the minimum dt value.

  char dt_set_by_species
    [32]; // For DT_SET_BY_SPECIES: the name of the species whose dt we are using to set the maximum dt for this species. e.g. "elc"
};

// Parameters for a chain of df/dt multipliers. Components are applied in order.
struct gkyl_gyrokinetic_fdot_multiplier {
  int num_multipliers;
  struct gkyl_gyrokinetic_fdot_multiplier_comp multiplier[GKYL_MAX_FDOT_MUL];
};

// Parameters for collisionless terms.
struct gkyl_gyrokinetic_collisionless {
  enum gkyl_gk_collisionless_type type; // Type of collisionless terms.
  bool write_diagnostics; // Whether to output diagnostics.
  double scale_factor; // Factor multiplying collisionless terms (should be > 0).
  // Passive advection speeds in x, y, z (for GKYL_GK_COLLISIONLESS_PASSIVE).
  // Assumes no advection/dependence on vpar/mu. Should return cdim values.
  evalf_t passive_speeds;
  void *passive_speeds_ctx; // Context for passive_speeds.
  // Gyrokinetic species only: multiply the collisionless RHS and CFL rate after scale_factor.
  // Collisions and sources are unaffected. An empty chain leaves the update unchanged.
  struct gkyl_gyrokinetic_fdot_multiplier time_rate_multiplier;
};

// Parameters for gk species.
struct gkyl_gyrokinetic_species {
  char name[128]; // Species name.

  double charge, mass; // Charge and mass.
  int vdim; // Velocity-space dimensions.
  double lower[GKYL_MAX_VDIM], upper[GKYL_MAX_VDIM]; // Lower, upper bounds of velocity-space.
  int cells[GKYL_MAX_VDIM]; // Velocity-space cells.

  struct gkyl_mapc2p_inp mapc2p;

  bool is_static; // Set to true if species does not change in time.

  struct gkyl_gyrokinetic_positivity positivity; // Positivity enforcement options.

  // Initial conditions using projection routine.
  struct gkyl_gyrokinetic_projection projection;
  // Initial conditions from a file.
  struct gkyl_gyrokinetic_ic_import init_from_file;

  // Ordered list of phase-space fields multiplying df/dt.
  struct gkyl_gyrokinetic_fdot_multiplier time_rate_multiplier;

  double polarization_density; // Density factor in LHS of quasineutrality eqn.

  // Whether to scale the density using a polarization solve
  bool scale_with_polarization;

      gkcls->fdot_scaling = gk_species_collisionless_fdot_scaling_enabled;
    }

    if (gkcls->write_diagnostics) {
      gkcls->flux_surf_ho = mkarr(false, gkcls->flux_surf->ncomp, gkcls->flux_surf->size);
      gkcls->write_diags_func = gk_species_collisionless_write_diags_enabled;
    }
  }
}

void
gk_species_collisionless_flux(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin
)
{
  gkcls->flux_func(app, species, gkcls, fin);
}

void
gk_species_collisionless_rhs(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin, struct gkyl_array *rhs
)
{
  gkcls->rhs_func(app, species, gkcls, fin, rhs);

  // At this point rhs and cflrate contain only collisionless terms, including scale_factor.
  // Compute the multiplier from this CFL rate and apply the same multiplier to the RHS
  // before collisions, damping, diffusion, radiation, reactions, or sources are added.
  gk_species_fdot_multiplier_advance_times_cfl(
    app, species, &gkcls->fdot_mult, app->field->phi_smooth, fin, species->cflrate
  );
  gk_species_fdot_multiplier_advance_times_rate(
    app, species, &gkcls->fdot_mult, app->field->phi_smooth, fin, rhs
  );
}

